{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from json.encoder import encode_basestring, _make_iterencode

CATALOG_PATH = "/root/therapy_catalog.json"
BAG_COST_PATH = "/root/bag_supply_cost.csv"
DELIVERY_PAYMENT_PATH = "/root/delivery_payment.csv"
PATIENT_OVERRIDES_PATH = "/root/patient_overrides.csv"
ANALYSIS_OUT = "/root/infusion_batch_analysis.json"
SUMMARY_OUT = "/root/infusion_batch_summary.md"


class Fixed2(float):
    """Float subclass encoded as a JSON number with exactly two decimal places."""


class Fixed2JSONEncoder(json.JSONEncoder):
    def iterencode(self, o, _one_shot=False):
        # Based on json.JSONEncoder.iterencode, with a custom float stringifier for Fixed2.
        if self.check_circular:
            markers = {}
        else:
            markers = None
        _encoder = encode_basestring

        def floatstr(value, allow_nan=self.allow_nan):
            if isinstance(value, Fixed2):
                return format(value, ".2f")
            if value != value:
                text = "NaN"
            elif value == float("inf"):
                text = "Infinity"
            elif value == float("-inf"):
                text = "-Infinity"
            else:
                return float.__repr__(value)
            if not allow_nan:
                raise ValueError("Out of range float values are not JSON compliant: " + repr(value))
            return text

        _iterencode = _make_iterencode(
            markers,
            self.default,
            _encoder,
            self.indent,
            floatstr,
            self.key_separator,
            self.item_separator,
            self.sort_keys,
            self.skipkeys,
            _one_shot,
        )
        return _iterencode(o, 0)


def clean_value(value):
    if value is None:
        return ""
    return str(value).strip()


def read_clean_csv(path):
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        reader.fieldnames = [clean_value(h) for h in (reader.fieldnames or [])]
        rows = []
        for row in reader:
            rows.append({clean_value(k): clean_value(v) for k, v in row.items()})
    return reader.fieldnames or [], rows


def include_flag(value):
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() == "true"


def load_catalog_therapies(catalog):
    if isinstance(catalog, list):
        candidates = catalog
    elif isinstance(catalog, dict):
        if isinstance(catalog.get("therapies"), list):
            candidates = catalog["therapies"]
        elif isinstance(catalog.get("service_lines"), list):
            candidates = []
            for service_line in catalog["service_lines"]:
                candidates.extend(service_line.get("therapies", []))
        else:
            candidates = []
            for value in catalog.values():
                if isinstance(value, list):
                    candidates.extend([x for x in value if isinstance(x, dict) and "therapy_code" in x])
    else:
        candidates = []
    return [t for t in candidates if include_flag(t.get("include_in_review"))]


def norm_label(value):
    return clean_value(value).casefold()


def to_int(value, label):
    try:
        return int(str(value).strip())
    except Exception as exc:
        raise ValueError(f"Could not parse integer for {label}: {value!r}") from exc


def to_float(value, label):
    try:
        return float(str(value).strip())
    except Exception as exc:
        raise ValueError(f"Could not parse number for {label}: {value!r}") from exc


def currency(value):
    return Fixed2(round(float(value), 2))


def find_patient_count_column(headers):
    normalized = {h.casefold().replace(" ", "_").replace("-", "_"): h for h in headers}
    preferred = [
        "active_patients",
        "patient_count",
        "patients",
        "active_patient_count",
        "current_patients",
        "num_patients",
        "patient_total",
    ]
    for name in preferred:
        if name in normalized:
            return normalized[name]
    for h in headers:
        n = h.casefold()
        if "patient" in n:
            return h
    raise ValueError(f"No patient count column found in headers: {headers}")


def main():
    with open(CATALOG_PATH, encoding="utf-8") as f:
        catalog = json.load(f)

    bag_headers, bag_rows = read_clean_csv(BAG_COST_PATH)
    payment_headers, payment_rows = read_clean_csv(DELIVERY_PAYMENT_PATH)
    patient_headers, patient_rows = read_clean_csv(PATIENT_OVERRIDES_PATH)

    print("bag_supply_cost headers:", bag_headers)
    print("delivery_payment headers:", payment_headers)
    print("patient_overrides headers:", patient_headers)

    in_scope = load_catalog_therapies(catalog)
    in_scope_by_code = {clean_value(t.get("therapy_code")): t for t in in_scope}
    print("filtered therapies:", json.dumps([
        {"therapy_code": t.get("therapy_code"), "therapy_name": t.get("therapy_name")} for t in in_scope
    ], indent=2))

    alias_map = {}
    for therapy in in_scope:
        names = [therapy.get("therapy_name", "")]
        aliases = therapy.get("aliases") or []
        if isinstance(aliases, list):
            names.extend(aliases)
        for name in names:
            key = norm_label(name)
            if key:
                alias_map[key] = therapy

    bag_cost_by_size = {}
    for row in bag_rows:
        size = to_int(row["bag_size_ml"], "bag_size_ml")
        bag_cost_by_size[size] = to_float(row["bag_supply_cost_usd"], "bag_supply_cost_usd")

    payment_by_code = {}
    matched_payments = []
    for row in payment_rows:
        label = row.get("therapy_label", "")
        therapy = alias_map.get(norm_label(label))
        if not therapy:
            continue
        code = clean_value(therapy["therapy_code"])
        payment = to_float(row["payment_per_delivery_per_patient_usd"], "payment_per_delivery_per_patient_usd")
        payment_by_code[code] = payment
        matched_payments.append({
            "therapy_label": label,
            "therapy_code": code,
            "payment_per_delivery_per_patient_usd": payment,
        })
    print("matched payments:", json.dumps(matched_payments, indent=2))

    patient_col = find_patient_count_column(patient_headers)
    print("patient count column selected:", patient_col)
    approved_latest = {}
    for row in patient_rows:
        status = row.get("status", "")
        if status.casefold() != "approved":
            continue
        code = clean_value(row.get("therapy_code", ""))
        if code not in in_scope_by_code:
            continue
        revision = to_int(row.get("revision", "0"), "revision")
        patients = to_int(row.get(patient_col, "0"), patient_col)
        prior = approved_latest.get(code)
        if prior is None or revision > prior["revision"]:
            approved_latest[code] = {"revision": revision, "active_patients": patients}
    patient_counts = {code: data["active_patients"] for code, data in approved_latest.items()}
    print("patient counts:", json.dumps(patient_counts, indent=2, sort_keys=True))

    therapies_out = []
    for therapy in sorted(in_scope, key=lambda t: clean_value(t.get("therapy_code"))):
        code = clean_value(therapy["therapy_code"])
        name = clean_value(therapy.get("therapy_name", ""))
        drug_cost_per_1000 = to_float(therapy["drug_cost_per_1000_mg_usd"], "drug_cost_per_1000_mg_usd")
        dose = to_float(therapy["dose_mg_per_day"], "dose_mg_per_day")
        bag_size = to_int(therapy["bag_size_ml"], "bag_size_ml")
        if bag_size not in bag_cost_by_size:
            raise KeyError(f"No bag supply cost for bag_size_ml={bag_size} therapy_code={code}")
        if code not in payment_by_code:
            raise KeyError(f"No delivery payment resolved for in-scope therapy_code={code}")
        if code not in patient_counts:
            raise KeyError(f"No approved patient override resolved for in-scope therapy_code={code}")

        bag_supply_cost = bag_cost_by_size[bag_size]
        payment = payment_by_code[code]
        active_patients = patient_counts[code]

        annual_drug_cost_7 = drug_cost_per_1000 * active_patients * dose * 7 * 52 / 1000
        annual_supply_cost_7 = bag_supply_cost * active_patients * 52
        annual_revenue_7 = payment * active_patients * 52
        annual_margin_7 = annual_revenue_7 - annual_drug_cost_7 - annual_supply_cost_7

        annual_drug_cost_14 = drug_cost_per_1000 * active_patients * dose * 14 * 26 / 1000
        annual_supply_cost_14 = bag_supply_cost * active_patients * 26
        annual_revenue_14 = payment * active_patients * 26
        annual_margin_14 = annual_revenue_14 - annual_drug_cost_14 - annual_supply_cost_14
        margin_difference = annual_margin_14 - annual_margin_7

        therapies_out.append({
            "therapy_code": code,
            "therapy_name": name,
            "active_patients": active_patients,
            "bag_size_ml": bag_size,
            "drug_cost_per_1000_mg_usd": currency(drug_cost_per_1000),
            "dose_mg_per_day": dose,
            "bag_supply_cost_usd": currency(bag_supply_cost),
            "payment_per_delivery_per_patient_usd": currency(payment),
            "annual_drug_cost_7": currency(annual_drug_cost_7),
            "annual_supply_cost_7": currency(annual_supply_cost_7),
            "annual_revenue_7": currency(annual_revenue_7),
            "annual_margin_7": currency(annual_margin_7),
            "annual_drug_cost_14": currency(annual_drug_cost_14),
            "annual_supply_cost_14": currency(annual_supply_cost_14),
            "annual_revenue_14": currency(annual_revenue_14),
            "annual_margin_14": currency(annual_margin_14),
            "margin_difference": currency(margin_difference),
        })

    total_7 = sum(float(t["annual_margin_7"]) for t in therapies_out)
    total_14 = sum(float(t["annual_margin_14"]) for t in therapies_out)
    total_diff = total_14 - total_7
    abs_diff = abs(total_diff)
    decision = "move_to_14_day" if abs_diff < 15000 else "keep_7_day"
    justification = (
        f"Absolute total margin difference is ${abs_diff:.2f}, "
        f"which is {'below' if abs_diff < 15000 else 'at or above'} the $15000 threshold."
    )

    analysis = {
        "assumptions": {
            "in_scope_filter": "include_in_review is boolean true or string 'true'",
            "delivery_payment_resolution": "therapy_label matched against in-scope therapy_name and aliases, case-insensitive after trimming whitespace",
            "patient_override_resolution": "approved rows only, case-insensitive status; highest revision retained per in-scope therapy_code",
            "patient_count_column": patient_col,
            "currency_rounding": "currency values rounded to 2 decimal places",
            "models": {
                "7_day": {"deliveries_per_year": 52, "days_per_delivery": 7},
                "14_day": {"deliveries_per_year": 26, "days_per_delivery": 14},
            },
            "decision_rule": "move_to_14_day if absolute total margin difference is less than 15000 USD, otherwise keep_7_day",
        },
        "therapies": therapies_out,
        "totals": {
            "total_annual_margin_7_day_usd": currency(total_7),
            "total_annual_margin_14_day_usd": currency(total_14),
            "total_annual_margin_difference_14_minus_7_usd": currency(total_diff),
            "absolute_total_margin_difference_usd": currency(abs_diff),
        },
        "recommendation": {
            "decision": decision,
            "justification": justification,
        },
    }

    with open(ANALYSIS_OUT, "w", encoding="utf-8") as f:
        json.dump(analysis, f, indent=2, cls=Fixed2JSONEncoder)
        f.write("\n")

    summary_lines = [
        "Infusion batch analysis summary",
        f"Total 7-day margin (USD): ${total_7:.2f}",
        f"Total 14-day margin (USD): ${total_14:.2f}",
        f"Absolute difference (USD): ${abs_diff:.2f}",
        f"Final decision: {decision}",
        justification,
    ]
    with open(SUMMARY_OUT, "w", encoding="utf-8") as f:
        f.write("\n".join(summary_lines) + "\n")

    print(f"Wrote {ANALYSIS_OUT}")
    print(f"Wrote {SUMMARY_OUT}")


if __name__ == "__main__":
    main()
","cross_profile":false}

